-- Hosbah (MH-576 B11): a team's own saved site templates — declarative YAML that scaffolds a ready
-- -to-deploy app in one step (internal/sitetemplate parses, validates and renders it; this row only
-- stores the source plus a few columns duplicated for cheap listing). driver is one of the small
-- typed registry in internal/sitetemplate (laravel, nextjs, node-api, static-site, django,
-- wordpress-docker, …), re-validated against source_yaml on every read so the registry stays the
-- single source of truth. name/description/driver here are read from the parsed document at save
-- time; a template can never hold a secret in plain text (internal/sitetemplate.Template.Validate
-- rejects a `secret: true` env with a literal value — only generate or a `from` reference to a data
-- service the caller already has running is allowed).
ALTER TABLE site_templates ADD CONSTRAINT site_templates_name_check CHECK (length(name) BETWEEN 1 AND 80);
ALTER TABLE site_templates ADD CONSTRAINT site_templates_team_id_name_key UNIQUE (team_id, name);
CREATE INDEX site_templates_team_idx ON site_templates (team_id);
